#!/usr/bin/env node
// typeship — MCP server. Generated by typeship — https://typeship.dev
// Two transports, zero dependencies:
//   node mcp.js            stdio (newline-delimited JSON-RPC 2.0)
//   node mcp.js --http     Streamable HTTP on PORT (default 3000)
// handleHttp() is exported for serverless/worker runtimes.
// In HTTP mode an incoming Authorization header is forwarded to the
// upstream API (per-request passthrough); stdio uses environment auth.

import { createInterface } from "node:readline";
import { TypeshipClient } from "./index";
import { OPS, buildArgs, missingRequired, type OpSpec } from "./ops";

const SERVER_NAME = "typeship-mcp";
const SERVER_VERSION = "1.0.0";
const PROTOCOL_VERSION = "2025-03-26";
const DEFAULT_BASE_URL = "https://typeship.dev/api/v1";
const AUTH_SCALARS: { option: string; flag: string; env: string }[] = [{"option":"bearerToken","flag":"token","env":"TYPESHIP_TOKEN"}];
const BASIC: { envUser: string; envPass: string } | null = null;
/** Authorization server for OAuth discovery (RFC 9728), from the spec. */
const OAUTH_ISSUER: string | null = null;

function makeClient(): TypeshipClient {
  const options: Record<string, unknown> = {};
  const baseUrl = process.env["TYPESHIP_BASE_URL"] ?? DEFAULT_BASE_URL ?? undefined;
  if (baseUrl === undefined) {
    process.stderr.write("No base URL: set TYPESHIP_BASE_URL in the MCP server env.\n");
    process.exit(1);
  }
  options.baseUrl = baseUrl;
  for (const a of AUTH_SCALARS) {
    const v = process.env[a.env];
    if (v !== undefined) options[a.option] = v;
  }
  if (BASIC) {
    const username = process.env[BASIC.envUser];
    const password = process.env[BASIC.envPass];
    if (username !== undefined && password !== undefined) options.basicAuth = { username, password };
  }
  return new TypeshipClient(options as never);
}

const client = makeClient();

interface JsonRpcRequest {
  jsonrpc: "2.0";
  id?: number | string | null;
  method: string;
  params?: Record<string, unknown>;
}

function toolDefinitions(): unknown[] {
  return OPS.map((op) => ({
    name: op.tool,
    description:
      (op.summary ? op.summary + " — " : "") + op.httpMethod + " " + op.path +
      (op.paginated ? " (paginated: returns one page plus hasMore)" : ""),
    inputSchema: op.select
      ? {
          ...op.inputSchema,
          properties: {
            ...(op.inputSchema.properties as Record<string, unknown>),
            select: { type: "string", description: 'GraphQL selection set override, e.g. "{ id name }"' },
          },
        }
      : op.inputSchema,
  }));
}

async function callTool(
  op: OpSpec,
  args: Record<string, unknown>,
  authHeader?: string,
): Promise<{ text: string; isError: boolean }> {
  const values: Record<string, unknown> = {};
  for (const p of op.params) {
    if (args[p.name] !== undefined) values[p.name] = args[p.name];
  }
  const missing = missingRequired(op, values).filter((name) => !(op.bodyStyle === "data" && name === "body" && args.body !== undefined));
  if (missing.length > 0) {
    return { text: "Missing required argument(s): " + missing.join(", "), isError: true };
  }
  const callArgs = buildArgs(
    op,
    values,
    op.bodyStyle === "data" ? args.body : undefined,
    typeof args.select === "string" ? args.select : undefined,
  );
  if (authHeader) {
    callArgs.push({ headers: { Authorization: authHeader } });
  }
  const target = (client as unknown as Record<string, Record<string, (...a: unknown[]) => unknown>>)[op.resource]!;
  try {
    const result = await (target[op.method]!(...callArgs) as Promise<{ ok: boolean; data?: unknown; error?: unknown }>);
    if (result.ok) {
      if (op.paginated) {
        const page = result.data as { items: unknown[]; hasNextPage(): boolean };
        return { text: JSON.stringify({ items: page.items, hasMore: page.hasNextPage() }, null, 2), isError: false };
      }
      return { text: JSON.stringify(result.data ?? { ok: true }, null, 2), isError: false };
    }
    const e = result.error as { name?: string; message?: string; status?: number; body?: unknown };
    return {
      text: JSON.stringify({ error: e?.name ?? "Error", message: e?.message, status: e?.status, body: e?.body }, null, 2),
      isError: true,
    };
  } catch (e) {
    return { text: (e as Error).message ?? "Tool call failed", isError: true };
  }
}

async function handleRpc(
  request: JsonRpcRequest,
  authHeader?: string,
): Promise<Record<string, unknown> | null> {
  const id = request.id ?? null;
  const reply = (result: unknown) => ({ jsonrpc: "2.0", id, result });
  const replyError = (code: number, message: string) => ({ jsonrpc: "2.0", id, error: { code, message } });

  switch (request.method) {
    case "initialize":
      return reply({
        protocolVersion: typeof request.params?.protocolVersion === "string" ? request.params.protocolVersion : PROTOCOL_VERSION,
        capabilities: { tools: {} },
        serverInfo: { name: SERVER_NAME, version: SERVER_VERSION },
      });
    case "ping":
      return reply({});
    case "tools/list":
      return reply({ tools: toolDefinitions() });
    case "tools/call": {
      const name = request.params?.name;
      const op = OPS.find((o) => o.tool === name);
      if (!op) return replyError(-32602, "Unknown tool: " + String(name));
      const args = (request.params?.arguments ?? {}) as Record<string, unknown>;
      const { text, isError } = await callTool(op, args, authHeader);
      return reply({ content: [{ type: "text", text }], isError });
    }
    default:
      if (request.method.startsWith("notifications/")) return null;
      if (request.id === undefined) return null;
      return replyError(-32601, "Method not found: " + request.method);
  }
}

// ---- Streamable HTTP transport ---------------------------------------------

const CORS_HEADERS: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, Mcp-Session-Id, Mcp-Protocol-Version",
};

function protectedResourceMetadata(origin: string): Record<string, unknown> {
  return {
    resource: origin,
    ...(OAUTH_ISSUER ? { authorization_servers: [OAUTH_ISSUER] } : {}),
    bearer_methods_supported: ["header"],
  };
}

/** Fetch-style handler: mount in any runtime (workers, serverless, node). */
export async function handleHttp(request: Request): Promise<Response> {
  const url = new URL(request.url);
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }
  if (url.pathname.endsWith("/.well-known/oauth-protected-resource")) {
    return new Response(JSON.stringify(protectedResourceMetadata(url.origin)), {
      headers: { ...CORS_HEADERS, "Content-Type": "application/json" },
    });
  }
  if (request.method !== "POST") {
    return new Response(JSON.stringify({ error: "POST JSON-RPC messages to this endpoint." }), {
      status: 405,
      headers: { ...CORS_HEADERS, "Content-Type": "application/json" },
    });
  }

  const authHeader = request.headers.get("authorization") ?? undefined;
  const envHasAuth = AUTH_SCALARS.some((a) => process.env[a.env] !== undefined);
  if (OAUTH_ISSUER && !authHeader && !envHasAuth) {
    return new Response(JSON.stringify({ error: "Authorization required." }), {
      status: 401,
      headers: {
        ...CORS_HEADERS,
        "Content-Type": "application/json",
        "WWW-Authenticate": 'Bearer resource_metadata="' + url.origin + '/.well-known/oauth-protected-resource"',
      },
    });
  }

  let message: JsonRpcRequest;
  try {
    message = (await request.json()) as JsonRpcRequest;
  } catch {
    return new Response(JSON.stringify({ jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } }), {
      status: 400,
      headers: { ...CORS_HEADERS, "Content-Type": "application/json" },
    });
  }
  const response = await handleRpc(message, authHeader);
  if (response === null) {
    return new Response(null, { status: 202, headers: CORS_HEADERS });
  }
  return new Response(JSON.stringify(response), {
    headers: { ...CORS_HEADERS, "Content-Type": "application/json" },
  });
}

function startHttp(port: number): void {
  void import("node:http").then(({ createServer }) => {
    createServer((req, res) => {
      let body = "";
      req.on("data", (chunk) => (body += chunk));
      req.on("end", () => {
        void handleHttp(
          new Request("http://localhost:" + port + (req.url ?? "/"), {
            method: req.method,
            headers: Object.fromEntries(
              Object.entries(req.headers).map(([k, v]) => [k, Array.isArray(v) ? v.join(", ") : String(v ?? "")]),
            ),
            ...(req.method === "POST" ? { body } : {}),
          }),
        ).then(async (response) => {
          res.statusCode = response.status;
          response.headers.forEach((value, key) => res.setHeader(key, value));
          res.end(await response.text());
        });
      });
    }).listen(port, () => {
      process.stderr.write(SERVER_NAME + " listening on http://localhost:" + port + "\n");
    });
  });
}

function startStdio(): void {
  const rl = createInterface({ input: process.stdin });
  rl.on("line", (line) => {
    const trimmed = line.trim();
    if (trimmed === "") return;
    let request: JsonRpcRequest;
    try {
      request = JSON.parse(trimmed) as JsonRpcRequest;
    } catch {
      process.stdout.write(JSON.stringify({ jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } }) + "\n");
      return;
    }
    void handleRpc(request)
      .then((response) => {
        if (response !== null) process.stdout.write(JSON.stringify(response) + "\n");
      })
      .catch((e) => {
        if (request.id !== undefined) {
          process.stdout.write(JSON.stringify({ jsonrpc: "2.0", id: request.id ?? null, error: { code: -32603, message: (e as Error).message ?? "Internal error" } }) + "\n");
        }
      });
  });
  rl.on("close", () => process.exit(0));
}

const invokedDirectly = typeof process.argv[1] === "string" && /mcp\.(js|mjs|ts)$/.test(process.argv[1]);
if (invokedDirectly) {
  const httpFlag = process.argv.indexOf("--http");
  if (httpFlag !== -1) {
    const port = Number(process.argv[httpFlag + 1]) || Number(process.env.PORT) || 3000;
    startHttp(port);
  } else {
    startStdio();
  }
}
